INSERT INTO project(id, tldr, project_name, start_date, end_date, main_points, project_description, linked_interests, linked_technologys, cateorys, stared_project, active) VALUES (1, 'A free game on Steam I made with two other devs. Downloaded 15,000+ times, with 2,500 leaderboard entries.', 'Scrambled Eggs', '2023-07-01', '2024-07-22', 'Unity & C# & Steamworks API & Aseprite', 'Free chicken tower defence on Steam: 15,000+ downloads and 2,500 leaderboard entries.', '1', '', '', 1, 1);
INSERT INTO project(id, tldr, project_name, start_date, end_date, main_points, project_description, linked_interests, linked_technologys, cateorys, stared_project, active) VALUES (2, 'A stock trading simulator I led a team of four on: buy, sell, track your orders and check your wallet.', 'Stock Trading Web Application', '2021-10-01', '2021-10-31', 'Java & Spring Boot & Spring Web & Spring Security & Thymeleaf & mySQL', 'A team-of-four stock trading simulator, led by me during the Albany Beck Pioneer Program.', '3', '', '', 0, 1);
INSERT INTO project(id, tldr, project_name, start_date, end_date, main_points, project_description, linked_interests, linked_technologys, cateorys, stared_project, active) VALUES (3, 'My final year project: a mobile game you steer by tilting your phone, with augmented reality.', 'Roadster Run', '2020-08-01', '2021-05-31', 'C# & Unity & Blender & Google AR Core', 'My final year project: a mobile game with motion controls and augmented reality.', '1', '', '', 1, 1);
