INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (1, 'Custom game backends on AWS for client projects, including Catan Universe and The Bornless.', 'SuperNimbus', 'Back-End Software Engineer', '2024-07-01', '2025-06-30', 'SuperNimbus is a contracting company that provides back-end services for gaming projects. It was a client-facing role: I worked out what each project needed and built custom back-end services for it, hosted on AWS.', '/assets/content/SuperNimbus.svg', 'TypeScript, JavaScript, C#, C++, AWS, PostgreSQL, NoSQL, gRPC, PlayFab, Grafana k6', 1);
INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (2, 'Java and Spring on the ICCP platform, mainly Smart Data: virtual cards for business payments.', 'Mastercard', 'Back-End Software Engineer II', '2023-02-01', '2024-07-31', 'At Mastercard I was a Back-End Software Engineer II, developing and maintaining the In Control for Commercial Payments (ICCP) platform, built with Java, Spring Framework and an Angular frontend. I worked mainly on the Smart Data project, a business-to-business solution for creating and controlling payments on virtual cards.', '/assets/content/mastercard-logo.png', 'Java, Shell Scripting, Linux Administration, Spring Boot, mySQL', 1);
INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (3, 'Contracted to the SBCI, building the customer hub where small businesses apply for reduced-rate loans.', 'Ergo (Contract: SBCI Customer Hub)', 'Full-Stack Software Developer', '2022-05-01', '2023-02-28', 'I was employed by Ergo, as a contractor for the Strategic Banking Corporation of Ireland (SBCI) to work on an emerging web application for the Irish Financial market, the SBCI customer hub. This application is a way for small businesses to access support for reduced-rate loans, allow for on-lenders to view and access these loan applications, and a system for the internal SBCI team to accept or deny these funding opportunities.', '/assets/content/ergo-logo.png', 'Java, JavaScript, AngularJS, Spring Boot, PSQL, HTML, CSS', 1);
INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (4, 'A six-month internship building cinema ticketing and showtime pages in Java, HTML and CSS.', 'usheru', 'Junior Full-Stack Developer (Internship)', '2020-02-01', '2020-08-31', 'Usheru is a film industry marketing and web services company, they provide many web solutions for film festivals, cinema ticketing services, and film online marketing. I was taken on as a Software Development Intern for six months. Here, I mainly worked on an application that was used to generate web pages and services that would provide ticket booking and show times. This application was created using Java, and we did some work on the generated pages using custom HTML and CSS.', '/assets/content/usheru-logo.png', 'Java, JavaScript, HTML, CSS, PSQL, Linux Scripting', 1);
INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (5, 'Six months of intensive Java EE, SQL and Spring training, straight after college.', 'Albany Beck Pioneer’s Program', 'Full-Stack Java Training Certificate', '2021-08-01', '2022-02-28', 'The Albany Beck Pioneers Program was a six-month intensive training program, which I attended directly after finishing my degree at The National College of Ireland. The aim of the program was to teach Java EE, SQL, and Spring Framework to graduates looking for employment in the technology industry.', '/assets/content/albany-logo.png', 'Java, Spring Framework, SQL', 1);
INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (6, 'BSc (Honours) in Computer Science, 2:1, specialising in software development.', 'National College of Ireland', 'BSc (Honours) in Computer Science', '2016-08-01', '2021-05-31', 'I achieved a Grade: of 2:1 in my Bachelor''s Degree in Computer Science in National College of Ireland. I specialized in Software Development. Here are some of the modules and projects I completed in my final 2 years.', '/assets/content/nci-logo.png', '', 1);
INSERT INTO work_experience(id, tldr, work_place, work_title, start_date, end_date, work_description, work_icon_url, technologys, active) VALUES (7, 'Full-stack on the ZIM eSIM app. I built the UK phone plan that lives on your eSIM, and the refunds for when an order goes wrong.', 'ZIM Connections', 'Full-Stack Software Engineer', '2025-06-01', NULL, 'ZIM Connections is an award-winning London start-up giving travellers and businesses affordable mobile eSIM data. It started out as a travel eSIM provider and has grown into B2B and the UK domestic mobile market. I work full-stack on the ZIM app for iPhone and Android, from the NestJS APIs and AWS infrastructure to the React Native screens.', '', 'TypeScript, NestJS, Fastify, React Native, PostgreSQL, Sequelize, AWS, Stripe, Elasticsearch, Socket.IO, Elastic APM, Mixpanel, Firebase, GitHub Actions', 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (1, 'About the game', 'text', '', 'A chicken tower defence game that finally answers "why did the chicken cross the road?" Throw wacky vehicles at the chicken hordes before they get to your corn, then fight your friends for the top of the leaderboards. Free on Steam for Windows and Mac, with no microtransactions.', 1, 1);
