INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (72, 'How we made it', 'text', '', 'Three of us made it: me as project manager and lead developer, with Anahat Mudgal and TheJackXBL. It''s Unity and C#, with the Steamworks API for achievements, stats and leaderboards. It came out on 22 July 2024 and has been downloaded 15,000+ times, with 2,500+ leaderboard entries.', 13, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (73, 'Where it started', 'text', '', 'It began as our entry to GMTK Game Jam 2023. The theme was "roles reversed", so we flipped Crossy Road: instead of getting a chicken across the road, you stop them. It placed 263rd out of nearly 7,000 games, and we liked it enough to make it into a full game.', 14, 1);
