INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (9, 'About the project', 'text', '', 'This stock trading platform web application was created using Java, SQL, and Spring Framework. The application was created with a team of four, which was led by me, during my time in the Albany Beck’s Pioneer Program. The application was created to simulate online stock traders/clients, where users can place orders (BUY & SELL) for trading, view their order status, view the trade order history, and access their asset purchases in the wallet.', 1, 2);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (10, 'Demo', 'video', 'https://www.youtube.com/embed/NSPweu8zZxk', '', 2, 2);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (11, 'GitHub repo', 'link', 'https://github.com/JakeHornerMan/TradingApp', '', 3, 2);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (12, 'About the game', 'text', '', 'Roadster Run was my final year project during my time at the National College of Ireland. It is a mobile phone game with motion controls and augmented reality (“AR”) functionality.', 1, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (13, 'Roadster Run', 'image', '/assets/content/RadsterRun.png', '', 2, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (14, 'Gameplay', 'text', '', 'The gameplay involves a car that moves on a procedurally generated road, where the enemy will come to attack the player. The player’s car is controlled by rotating the phone left or right to change lanes. The player can also shoot at any oncoming enemy car to gain points and dispatch them.', 3, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (15, 'Gameplay', 'video', 'https://www.youtube.com/embed/vYrNn3dqbnI', '', 4, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (16, 'Customization', 'text', '', 'The player can also customize their player car, which is reflected in the main game and AR functionality.', 5, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (17, 'Customization', 'video', 'https://www.youtube.com/embed/oRja2b9bjwM', '', 6, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (18, 'Augmented Reality', 'text', '', 'The AR functionality allows players to take images with their customized vehicles.', 7, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (19, 'Augmented Reality', 'video', 'https://www.youtube.com/embed/d_DhPFWfdK4', '', 8, 3);
