INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (24, 'About the project', 'text', '', 'I created a ‘Dark Souls’ inspired third-person character controller to practice my unity 3D programming.<?>This project included a function camera with Collision. All the inputs have also been mapped to the controller.', 1, 4);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (25, 'Demo', 'video', 'https://www.youtube.com/embed/RvzV5sXNClA', '', 2, 4);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (26, 'GitHub repo', 'link', 'https://github.com/JakeHornerMan/RougeSoulsLike', '', 3, 4);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (27, 'About the game', 'text', '', 'Blobber is a competitive platformer where players play as an escaped alien jumping on scientists for points. The player will need to dodge fireballs, which are being shot by a hazmat enemy flying in the sky, in order to conserve health.<?>‘Classic’ mode is a time trial mode where the player completes for points. The ‘Floor is Lava’ mode will damage the player when he touches the floor. There is a leaderboard integrated with ‘Google Play Games’, which allows players to compete in each mode. There is also an opt-in advertisement that allows the player to gain one extra health point.', 1, 5);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (28, 'Gameplay', 'video', 'https://www.youtube.com/embed/SaxCwbT1oE0', '', 2, 5);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (29, 'About the project', 'text', '', 'This is a project I made to showcase my knowledge of Microservices, Spring Boot, OOP, and MVC framework. I created a set of services that allows a user to create an account, sign in, and withdraw money in the form of notes (50s, 20s, 10s, and 5s).', 1, 6);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (30, 'GitHub repo', 'link', 'https://github.com/JakeHornerMan/BankingATM', '', 2, 6);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (31, 'About the game', 'text', '', 'This is a game that was created in seven days for the ''Weekly Game Jam'' 203. The theme for this game jam was ''Eat The Enemy''. My self and another game designer collaborated on this project.<?>Shy Chomper is an action stealth puzzle game, where the player avoids the gaze of the enemy ‘Blobbers’, and ‘Floating Eyes’. The player can only cross tiles marked by a specific color, by consuming a ‘Blobbler’ of the corresponding color.', 1, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (32, 'Gameplay', 'video', 'https://www.youtube.com/embed/LQHkxgCWXVg', '', 2, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (33, 'Levels', 'text', '', 'We created 5 levels to showcase the toll we built for this game inspired by mazes, board games, and top-down stealth games. Please feel free to follow the link below to give the levels a try!', 3, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (34, 'Play the Game here', 'link', 'https://jakehornerman.itch.io/shy-chompers-trip', '', 4, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, project_fk) VALUES (35, 'GitHub repo', 'link', 'https://github.com/JakeHornerMan/Game-Jam-J-J', '', 5, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (36, 'Projects', 'text', '', 'I have worked on is USM''s ''Catan Universe'', by provideing custom RPCs, front end updates, and server stress testing automation. I have also worked on a up and coming multiplayer shooter Cathedral''s ''The Bornless'', providing authentication, user statistics, and in-app purchases.', 1, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (37, 'Twitch Service Integration (The Bornless)', 'text', '', 'One of the requirements for ‘The Bornless’ was to have full Twitch integration to allow users to claim in-game items from watching streams of the game. This system was fully integrated using the Playfab system for authentication and user management with the CloudScript functionality in JavaScript.<?>The system will gather all ‘Claimed’ status items from the attached Twitch account. Grant them to the player Inventory, and set them to ‘Fulfilled’ status. Of course, contacting multiple endpoints we need fallback mechanisms when there is a failure along the progress of the system, All failed Items are stored against the player''s title data in a small JSON object. This object will be retried once the system is called, and be cleared when all items have been successfully granted to the player.', 2, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (38, 'Economy Updates for granting Items (The Bornless)', 'text', '', 'The Item grants system for ‘The Bornless’ backend project was previously implemented using the legacy Economy V1 with no fallback for any item failures, this could cause a major problem with the user not receiving items when they should if an endpoint failed. I was tasked with the implementation of a system that would store any failures and retry them at a later date. While I was developing this system I updated all instances of granting items to the new Economy V2 endpoints.<?>This system would store any failed item information in a new Dynamo DB table while it was attempting to grant items to each user. I managed to flesh out the common reasons why these items would fail and when recognized would attach it to the table, for example, if an item was attempted to be granted that was not created in the Econmy system on Playfab. A second socket endpoint was created on this back project to be called that would once again retry these failed items.', 3, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (39, 'Privacy Popup Updates (Catan | IOS)', 'text', '', 'A policy change came through for the IOS store that directly affected the ‘Catan Universe’ application and its release of the next update. The solution for this was to add an info popup at the start of each new install of the application. Also, it was required that this popup would be translated into 6 other popular languages.', 4, 1);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (40, 'Health check web services', 'text', '', 'I have made considerable contributions to developing web services for a health check system active in this platform with Java EE and Spring Framework, creating endpoints that will be consumed by both customers and internal teams.', 1, 2);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (41, 'Health Check Separation', 'text', '', 'The health check system was an endpoint that allowed internal and external customers to check the status of the ICCP application. This functionality was split into endpoints, shallow health returning a simple “status: UP” or “status: DOWN”, and deep health returning an in-depth analysis of all components relating to the ICCP application. These 2 endpoints would gather this information from cached values stored and logged by a background service every 30 seconds.<?>I was tasked with separating these two endpoints functionality, and making them have independent run times for caching and logging, 5 seconds for shallow, and 5 minutes for deep. Also, I was tasked with having the shallow endpoint return the cached value, while the deep endpoint would run the health check service independently and return the current status values.<?>I focused on the separation of the Heath check service into two by creating a DeepHealthService class and a ShallowHealthService class, also creating independent flags and variables to support this separation.<?>I used multithreading to create another scheduling task, that will be running DeepHealthService. I also created another cache store and logging functionality, for this value to be stored every 5 minutes. The previous thread handling the old implementation of health check service, was then repurposed to run the ShallowHealthService.<?>Finally, I pointed the deep endpoint that accessed the cached value, to now do an independent call to my DeepHealthService, and return this value to the end user.', 2, 2);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (42, 'Hashi Migration', 'text', '', 'There are many different applications that come together to make up the ICCP Platform. When each application contacts the other they have a passphrase type validation to verify that another application is from the MasterCard suite of applications. My Team, Team Vision was in charge of migrating this system to a new solution HashiCorp Vault. We were in charge of migrating CommercialAPI, PurchaseControlUI, CommercialApi Batch, and CommercialApi Report.<?>Mastercard has many different environments where applications are deployed and tested, Stage 1, Stage 2, Performance testing, MTF, MTF2. On top of these servers, we also need to migrate the servers based in the United States and India. We were provided with a ‘Cookbook solution’ by an alternative team on basic settings and procedures we should be doing to migrate servers.<?>As a Team, we had to develop a set of Instructions and Validations that needed to be carried out by members of Mastercard (BizOps) who have in-depth access to all server and Jenkins configurations. We created Pull Requests for each environment, that merged the new Hashi configurations on each of these specific servers. When these instructions were finalised, we needed to create a CRQ session with BizOps to carry out our steps and validations.<?>A major part I played in the Hashi Migration CRQ sessions with BizOps, was for the 8 servers in India. Mastercard cycles between an Active server set each weekend, 2 sets for 4 application. Due to our ICCP platform being a business solution, the best time to do this migration was on the weekend. We did the inactive set of 4 servers on Saturday, steps for migration, and validated the application functionality. That evening an alternative team performed with a cutover of making the migrated Hashi servers active, while also making the remaining 4 servers inactive. We then proceeded with the Hashi migration of the inactive servers on Sunday.', 3, 2);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (43, 'SBCI', 'image', '/assets/content/sbci-logo.png', '', 1, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (44, 'Application Flow Rework', 'text', '', 'There were several different loan schemes available for customers using the SBCI customer hub, where a user could select and fill out various pages to see if they were eligible for a reduced-rate loan. When a user selects a scheme it has a hard-coded set of eight pages that would need to be completed in order to apply for that loan. The introduction of the ‘Ukraine Credit Guarantee Scheme’ aimed at providing financial aid to businesses affected by the Ukraine crisis, the business needs required a new page progression to calculate if a customer was eligible for a subsidized loan.<?>I created a new component that allows the loan application to take in the scheme name and populate the application with the necessary components, decouple the stepper functionality from the to allow it to be populated with the passed-on information, and also allow for reused pages from other schemes to be populated with necessary legal text for it to be used in multiple scheme types.<?>This system has been continued, and used to support many different loan application schemes.', 2, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (45, 'Responsive CSS framework', 'text', '', 'Before the release of the Customer Hub application, a major target for us was to restructure the design to fit all devices and be responsive to all screen sizes. When I joined the team I led the process with our UX designer to form a system using Flexbox CSS. Our goal was to keep the original design flow and philosophy while allowing smaller devices to be visible and intuitive.<?>I created a clear class-based system that allowed us to cut down on rewriting CSS code for each Angular component. We could then call clearly defined CSS classes and modifiers to allow each box of content to scale and restructure to allow the end user to access the app on any device.<?>Before release, we managed to restructure all of the customer-facing pages which include the login, loan application process pages, and the main menu with sub-menus. After release, we continued to bring the Flexbox CSS system to all other users including on lender and approvers.', 3, 3);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (46, 'TaskLogs', 'text', '', 'In Usheru a lot of information was scraped from the web to keep their internal ticketing system functional, this would be done through a shell script that would give output in the console if each process was successful. The information taken varied from showtimes, ticket numbers, seat information, streaming services, and review ratings. The issue with the current implementation was that it was only visible to the developers on the Usheru team if these processes had been run successfully or not.<?>I was tasked with creating a page for an internal admin user at usheru called ‘TaskLogs’, this contained various information for each task run by the information gathering shell script such as start time, end time, total time, did it completed successfully, how many records did it gather, and a JSON file output to see the record gathered.', 1, 4);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (47, 'Training', 'text', '', 'Albany Beck had a main focus on the financial industry and would provide us with interview opportunities with various UK financial services.<?>During training, we focused on the beginning of Java development, object-oriented programming, databases, database management, Spring Boot, Microservices with Spring Web, Authentication with Spring Security, Spring JDBC, and Spring MVC. Throughout the training we created many applications, with a final project created in the last week, which was a trading application. This application is documented on the ‘Software Projects Tab’ under the name ‘Stock Trading Web Application’.', 1, 5);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (48, '4th Year Modules', 'text', '', 'Software Project - Roadster Run project (included in the ''Software Projects'' tab)<?>Distributed Systems - Heart Attack Risk factor (Java & Grpc application)<?>Artificial Intelligence - Chess game (Java)<?>Data Application Development - Entertainment Industry Stock market analysis (R & Python)<?>Multimedia and Mobile Application Development - Uptime productivity app (Kotlin)', 1, 6);
