INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (57, 'UK domestic subscriptions', 'text', '', 'I led new product development on ZIM''s domestic subscription service, making ZIM one of the first eSIM start-ups to offer a full UK mobile experience: a UK phone number with monthly rolling data, calls and SMS, and no contract. I built the new plan selection, purchasing and subscription management screens, the REST endpoints that plug the new subscription data into our existing systems, and the mobile provider and Stripe subscription integrations behind it.', 1, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (58, 'Order failures and refunds', 'text', '', 'I designed and built the order failure and refund system end to end: automatic refunds on failed orders, user notifications, and a flow that offers an eligible replacement plan. It turned a manual support job into an automatic one, and stopped partner provider outages from costing us closed sales.', 2, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (59, 'eSIM wallet redesign', 'text', '', 'I led a full frontend redesign and backend rework of the eSIM wallet, pulling the business logic out of the visual components so they can be reused, with every screen built to the Figma designs.', 3, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (60, 'Plan selection and purchasing', 'text', '', 'I overhauled the plan selection and purchase flow, including new plan confirmation screens, and brought the UK domestic subscription plans into the same flow.', 4, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (61, 'White-label apps: ZIM@SBB and G+D Travel', 'text', '', 'Beyond the main ZIM app I''ve contributed to ZIM''s white-label B2B apps, which run on the same platform under a partner''s brand. ZIM@SBB, built in partnership with SBB (Swiss Federal Railways), sells eSIM data plans in over 200 destinations through a co-branded app, and G+D Travel does the same for Giesecke+Devrient. I help deliver and maintain them alongside the main app.', 5, 7);
INSERT INTO content(id, content_title, content_type, content_url, content_paragraph, position, work_experience_fk) VALUES (62, 'Keeping the lights on', 'text', '', 'Test coverage, a localised search bar, Elastic APM transactions, Mixpanel data collection, and migrating users onto our new backend infrastructure.', 6, 7);
